--
-- Table structure for table `comunidades`
--

DROP TABLE IF EXISTS `comunidades`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comunidades` (
  `id` int NOT NULL,
  `nome` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `complexo` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cor_hex` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `distrito` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `ids_social` decimal(5,4) DEFAULT NULL,
  `classe_prioridade` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origem_cartografica` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_ruas` int DEFAULT '0',
  `criado_em` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_com_complexo` (`complexo`),
  KEY `idx_com_distrito` (`distrito`),
  KEY `idx_com_nome` (`nome`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
