DROP TABLE IF EXISTS `equipamento_emails`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `equipamento_emails` (
  `id` int NOT NULL AUTO_INCREMENT,
  `equipamento_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'GERAL',
  `principal` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_eqmail_equip` (`equipamento_id`,`principal`),
  CONSTRAINT `fk_eqmail_equip` FOREIGN KEY (`equipamento_id`) REFERENCES `equipamentos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=451 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
